+     * @param v the other endpoint
+     * @return the newly created edge
+     */
+    public Edge addEdge(int u, int v) {
+        checkVertex(u);
+        checkVertex(v);
+        Edge edge = new Edge(u, v, edges.size());
+        edges.add(edge);
+        incidence.get(u).add(edge);
+        if (u != v) {
+            incidence.get(v).add(edge);
+        }
